// import { Environment } from '@game-studio/shell-connection-types';
import { Environment } from '@game-studio/utilities';

import { queryStringParams } from './query-string';

function detectEnvironment(): Environment {
    const hostname = window.location.hostname;

    if (queryStringParams.environment) {
        return queryStringParams.environment;
    }

    if (!hostname) {
        return 'debug';
    }

    switch (true) {
        case (hostname.indexOf('dev-') > -1):
        case (hostname.indexOf('.dev.') > -1):
            return 'dev';
        case (hostname.indexOf('stage-') > -1):
        case (hostname.indexOf('.stage.') > -1):
            return 'stage';
        case (hostname.indexOf('tombola') > -1):
            return 'live';
        default:
            return 'debug';
    }
}

export const environment = detectEnvironment();
